-- 5.571 municípios da base geográfica DTB 2025; chave = código IBGE de 7 dígitos.
-- Arquivo UTF-8. Execute com F5 no SQL Developer como MAPA_IDOSOS.
SET DEFINE OFF
WHENEVER SQLERROR EXIT SQL.SQLCODE ROLLBACK

MERGE INTO tab_municipio d USING (SELECT 1100015 id_municipio, 'Alta Floresta D''Oeste' nome, 11 id_uf FROM dual) s
ON (d.id_municipio = s.id_municipio)
WHEN MATCHED THEN UPDATE SET d.nome = s.nome, d.id_uf = s.id_uf
WHEN NOT MATCHED THEN INSERT (id_municipio, nome, id_uf) VALUES (s.id_municipio, s.nome, s.id_uf);
